import io

from importer import main


class FakeDB:
    def __init__(self):
        self.rows = []

    def insert_many(self, records):
        self.rows.extend(records)


def test_main_writes_and_reports():
    db, out = FakeDB(), io.StringIO()
    assert main([], ["a,1", "b,2"], db, out) == 0
    assert db.rows == [{"name": "a", "qty": 1}, {"name": "b", "qty": 2}]
    assert out.getvalue() == "imported 2 records\n"

