import sys


def parse_line(line):
    parts = line.strip().split(",")
    return {"name": parts[0], "qty": int(parts[1])}


def main(argv, lines, db, out=sys.stdout):
    records = [parse_line(l) for l in lines if l.strip()]
    if "--dry-run" in argv:
        out.write("[dry-run] would write %d records\n" % len(records))
        return 0
    db.insert_many(records)
    out.write("imported %d records\n" % len(records))
    return 0
